INSERT INTO public.word_illustrations (id, level, word, sort_order, sense, alt_zh, example, example_zh, image_url, local_path, style, version) VALUES
('elementary-cap-01-v1', 'elementary', 'cap', 1, '鴨舌帽', '藍色鴨舌帽有圓頂和向前伸出的帽簷。', 'My blue cap has a curved brim.', '我的藍色鴨舌帽有彎彎的帽簷。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/cap-01-v1.webp', '/images/vocabulary/elementary/cap-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-pen-01-v1', 'elementary', 'pen', 1, '原子筆', '一枝藍色原子筆，筆蓋放在旁邊，露出金屬筆尖。', 'I take the cap off my pen to write.', '我拿下原子筆的筆蓋來寫字。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/pen-01-v1.webp', '/images/vocabulary/elementary/pen-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-eraser-01-v1', 'elementary', 'eraser', 1, '橡皮擦', '一塊粉紅色長方形橡皮擦，邊角略圓。', 'This pink eraser helps me fix a mistake.', '這塊粉紅色橡皮擦幫我擦掉寫錯的地方。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/eraser-01-v1.webp', '/images/vocabulary/elementary/eraser-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-ruler-01-v1', 'elementary', 'ruler', 1, '尺', '一把斜放的木尺，上面有整齊的刻度。', 'I use a ruler to draw a straight line.', '我用尺畫一條直線。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/ruler-01-v1.webp', '/images/vocabulary/elementary/ruler-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-notebook-01-v1', 'elementary', 'notebook', 1, '筆記本', '一本攤開的藍色封面線圈筆記本，內頁空白。', 'I open my notebook to a blank page.', '我翻開筆記本到空白的一頁。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/notebook-01-v1.webp', '/images/vocabulary/elementary/notebook-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-paper-01-v1', 'elementary', 'paper', 1, '紙', '三張白紙稍微錯開疊放，一角微微捲起。', 'These sheets of paper are ready for drawing.', '這幾張紙可以拿來畫畫。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/paper-01-v1.webp', '/images/vocabulary/elementary/paper-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-desk-01-v1', 'elementary', 'desk', 1, '書桌', '一張木製書桌，有平坦桌面、四隻桌腳和兩個抽屜。', 'My desk has two drawers for school supplies.', '我的書桌有兩個抽屜可以放文具。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/desk-01-v1.webp', '/images/vocabulary/elementary/desk-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-table-01-v1', 'elementary', 'table', 1, '桌子', '一張圓形木桌，有四隻穩固的桌腳。', 'We sit around the round table for lunch.', '我們圍著圓桌吃午餐。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/table-01-v1.webp', '/images/vocabulary/elementary/table-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-bed-01-v1', 'elementary', 'bed', 1, '床', '一張木床，床上有白色枕頭和藍色棉被。', 'My bed has a soft blue blanket.', '我的床上有一條柔軟的藍色棉被。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/bed-01-v1.webp', '/images/vocabulary/elementary/bed-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-clock-01-v1', 'elementary', 'clock', 1, '時鐘', '一個綠色圓形時鐘，鐘面有刻度和兩根指針。', 'The clock helps us know when class begins.', '時鐘讓我們知道什麼時候開始上課。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/clock-01-v1.webp', '/images/vocabulary/elementary/clock-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-mirror-01-v1', 'elementary', 'mirror', 1, '鏡子', '一面橢圓形桌鏡，有木框和底座，鏡面映著淡藍色光。', 'I look in the mirror before school.', '我上學前照鏡子。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/mirror-01-v1.webp', '/images/vocabulary/elementary/mirror-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-door-01-v1', 'elementary', 'door', 1, '門', '一扇關上的棕色木門，裝有金色圓形門把。', 'Please knock on the door before coming in.', '進來之前請先敲門。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/door-01-v1.webp', '/images/vocabulary/elementary/door-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-window-01-v1', 'elementary', 'window', 1, '窗戶', '一扇白框窗戶分成四格，玻璃外可見淡藍色天空。', 'Blue sky is visible through the window.', '透過窗戶可以看見藍天。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/window-01-v1.webp', '/images/vocabulary/elementary/window-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-computer-01-v1', 'elementary', 'computer', 1, '電腦', '一台桌上型電腦，有螢幕、鍵盤和滑鼠，螢幕呈淡藍色。', 'I use the computer to practice English.', '我用電腦練習英文。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/computer-01-v1.webp', '/images/vocabulary/elementary/computer-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-phone-01-v1', 'elementary', 'phone', 1, '電話', '一支裝著藍綠色保護殼的手機，螢幕亮著淡藍色光。', 'I use the phone to call Grandma.', '我用電話打給奶奶。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/phone-01-v1.webp', '/images/vocabulary/elementary/phone-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-toy-01-v1', 'elementary', 'toy', 1, '玩具', '一個木製玩具火車頭，有紅色車身、黃色車頂和藍色輪子。', 'This wooden train is my favorite toy.', '這台木製火車是我最喜歡的玩具。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/toy-01-v1.webp', '/images/vocabulary/elementary/toy-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-doll-01-v1', 'elementary', 'doll', 1, '娃娃', '一個坐著的布娃娃，有棕色毛線頭髮，穿紫色洋裝。', 'The doll wears a purple dress.', '這個娃娃穿著紫色洋裝。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/doll-01-v1.webp', '/images/vocabulary/elementary/doll-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-kite-01-v1', 'elementary', 'kite', 1, '風箏', '一個紅黃藍綠相間的菱形風箏，有繫著蝴蝶結的長尾巴。', 'My colorful kite has a long tail.', '我的彩色風箏有一條長尾巴。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/kite-01-v1.webp', '/images/vocabulary/elementary/kite-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-soccer-01-v1', 'elementary', 'soccer', 1, '足球運動', '一個孩子在草地上踢黑白足球，前方有小球門。', 'We play soccer on the grass after school.', '我們放學後在草地上踢足球。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/soccer-01-v1.webp', '/images/vocabulary/elementary/soccer-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-basketball-01-v1', 'elementary', 'basketball', 1, '籃球', '一顆橘色籃球，上面有深色弧形接縫。', 'I bounce the basketball before I shoot.', '我投籃前先拍球。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/basketball-01-v1.webp', '/images/vocabulary/elementary/basketball-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-baseball-01-v1', 'elementary', 'baseball', 1, '棒球', '一顆白色棒球，上面有兩排彎曲的紅色縫線。', 'The baseball has red stitches.', '這顆棒球有紅色縫線。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/baseball-01-v1.webp', '/images/vocabulary/elementary/baseball-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-gift-01-v1', 'elementary', 'gift', 1, '禮物', '一個包著粉紅色紙的禮物盒，上面繫著藍色蝴蝶結。', 'I wrap the gift with a blue ribbon.', '我用藍色緞帶把禮物包好。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/gift-01-v1.webp', '/images/vocabulary/elementary/gift-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-duck-01-v1', 'elementary', 'duck', 1, '鴨子', '一隻白色鴨子，有橘黃色扁嘴和兩隻橘色蹼腳。', 'The duck walks on its webbed feet.', '鴨子用有蹼的腳走路。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/duck-01-v1.webp', '/images/vocabulary/elementary/duck-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-cow-01-v1', 'elementary', 'cow', 1, '乳牛', '一頭黑白花紋的乳牛站著，有粉紅色鼻口和四隻蹄子。', 'The cow has black and white spots.', '這頭乳牛身上有黑白斑紋。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/cow-01-v1.webp', '/images/vocabulary/elementary/cow-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-pig-01-v1', 'elementary', 'pig', 1, '豬', '一隻粉紅色小豬，有圓鼻子、四隻短腿和捲尾巴。', 'The pink pig has a curly tail.', '這隻粉紅色的豬有捲捲的尾巴。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/pig-01-v1.webp', '/images/vocabulary/elementary/pig-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-sheep-01-v1', 'elementary', 'sheep', 1, '綿羊', '一隻綿羊站著，全身覆蓋蓬鬆的白色捲毛。', 'The sheep has soft white wool.', '這隻綿羊有柔軟的白色羊毛。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/sheep-01-v1.webp', '/images/vocabulary/elementary/sheep-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-horse-01-v1', 'elementary', 'horse', 1, '馬', '一匹棕色馬站著，有深棕色鬃毛和長尾巴。', 'The brown horse has a long tail.', '這匹棕色馬有一條長尾巴。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/horse-01-v1.webp', '/images/vocabulary/elementary/horse-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-monkey-01-v1', 'elementary', 'monkey', 1, '猴子', '一隻棕色猴子坐在低矮樹枝上，手裡拿著一根香蕉，身後有長尾巴。', 'The monkey holds a banana on the branch.', '猴子坐在樹枝上拿著一根香蕉。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/monkey-01-v1.webp', '/images/vocabulary/elementary/monkey-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-bee-01-v1', 'elementary', 'bee', 1, '蜜蜂', '一隻蜜蜂振翅飛著，有黃黑條紋、六隻腳和兩根觸角。', 'The bee flies with its tiny wings.', '蜜蜂用小小的翅膀飛行。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/bee-01-v1.webp', '/images/vocabulary/elementary/bee-01-v1.webp', 'watercolor-pencil-v1', 1),
('elementary-mouse-01-v1', 'elementary', 'mouse', 1, '老鼠', '一隻小灰鼠，有圓耳朵、鬍鬚和細長的粉紅色尾巴。', 'The little mouse has round ears.', '這隻小老鼠有圓圓的耳朵。', 'https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/elementary/mouse-01-v1.webp', '/images/vocabulary/elementary/mouse-01-v1.webp', 'watercolor-pencil-v1', 1)
